import fs from 'node:fs';
import path from 'node:path';

const KEY_RE = /^[a-f0-9]{32}$/;

// Stores blobs on local disk. Keys are generated by the server (32 hex chars), which rules out path traversal.
export class LocalStorage {
  constructor(dir) {
    this.dir = path.resolve(dir);
    this.tmpDir = path.join(this.dir, '.tmp');
    fs.mkdirSync(this.tmpDir, { recursive: true });
  }

  #path(key) {
    if (!KEY_RE.test(key)) throw new Error('Invalid storage key');
    return path.join(this.dir, key);
  }

  // Move an already-written temp file into permanent storage (a rename: same filesystem, no copy).
  async put(key, tempFilePath) {
    await fs.promises.rename(tempFilePath, this.#path(key));
  }

  createReadStream(key) {
    return fs.createReadStream(this.#path(key));
  }

  async remove(key) {
    await fs.promises.unlink(this.#path(key)).catch((err) => { if (err.code !== 'ENOENT') throw err; });
  }
}
